namespace edgeshield { namespace {
std::string json_escape(const std::string&s){std::string o;for(unsigned char c:s){switch(c){case '"':o+="\\\"";break;case '\\':o+="\\\\";break;case '\n':o+="\\n";break;case '\r':o+="\\r";break;case '\t':o+="\\t";break;default:if(c>=32)o+=char(c);}}return o;}
std::string getstr(const std::string&j,const std::string&k,const std::string&d=""){auto p=j.find("\""+k+"\"");if(p==std::string::npos)return d;p=j.find(':',p);if(p==std::string::npos)return d;p=j.find('"',p);if(p==std::string::npos)return d;auto e=j.find('"',p+1);if(e==std::string::npos)return d;return j.substr(p+1,e-p-1);}
double getnum(const std::string&j,const std::string&k,double d=0){auto p=j.find("\""+k+"\"");if(p==std::string::npos)return d;p=j.find(':',p);if(p==std::string::npos)return d;try{return std::stod(j.substr(p+1));}catch(...){return d;}}
std::string source_name(Source s){switch(s){case Source::Network:return"network";case Source::Url:return"url";case Source::Sms:return"sms";default:return"system";}}
std::string severity_name(Severity s){switch(s){case Severity::Low:return"low";case Severity::Medium:return"medium";case Severity::High:return"high";case Severity::Critical:return"critical";default:return"info";}}
std::string event_json(const DetectionResult&r){const auto&e=r.event;std::ostringstream o;o<<"{\"flagged\":"<<(r.flagged?"true":"false")<<",\"event_id\":\""<<json_escape(e.event_id)<<"\",\"source\":\""<<source_name(e.source)<<"\",\"category\":\""<<json_escape(e.category)<<"\",\"severity\":\""<<severity_name(e.severity)<<"\",\"confidence_heuristic\":"<<e.confidence<<",\"risk_score\":"<<e.risk_score<<",\"evidence\":[";for(std::size_t n=0;n<e.evidence.size();++n){if(n)o<<',';auto&v=e.evidence[n];o<<"{\"key\":\""<<json_escape(v.key)<<"\",\"value\":\""<<json_escape(v.value)<<"\",\"explanation\":\""<<json_escape(v.explanation)<<"\"}";}o<<"],\"recommended_actions\":[";for(std::size_t n=0;n<e.recommended_actions.size();++n){if(n)o<<',';o<<'\"'<<json_escape(e.recommended_actions[n])<<'\"';}o<<"]}";return o.str();}
std::string metrics_json(const SystemMetrics&m){std::ostringstream o;o<<"{\"platform\":\""<<m.platform<<"\",\"logical_cpu_count\":"<<m.logical_cpu_count<<",\"cpu_utilisation_percent\":";if(m.cpu_utilisation_percent)o<<*m.cpu_utilisation_percent;else o<<"null";o<<",\"memory_total_kb\":"<<(m.memory_total_kb?std::to_string(*m.memory_total_kb):"null")<<",\"memory_available_kb\":"<<(m.memory_available_kb?std::to_string(*m.memory_available_kb):"null")<<",\"storage_utilisation_percent\":"<<(m.root_storage_utilisation_percent?std::to_string(*m.root_storage_utilisation_percent):"null")<<",\"cpu_temperature_celsius\":"<<(m.cpu_temperature_celsius?std::to_string(*m.cpu_temperature_celsius):"null")<<",\"load\":["<<(m.load1?std::to_string(*m.load1):"null")<<','<<(m.load5?std::to_string(*m.load5):"null")<<','<<(m.load15?std::to_string(*m.load15):"null")<<"],\"uptime_seconds\":"<<(m.uptime_seconds?std::to_string(*m.uptime_seconds):"null")<<",\"cpu_cores\":[";for(std::size_t i=0;i<m.cpu_cores.size();++i){if(i)o<<',';o<<"{\"name\":\""<<m.cpu_cores[i].name<<"\",\"utilisation_percent\":"<<(m.cpu_cores[i].utilisation_percent?std::to_string(*m.cpu_cores[i].utilisation_percent):"null")<<'}';}o<<"],\"network_interfaces\":[";for(std::size_t i=0;i<m.network_interfaces.size();++i){if(i)o<<',';const auto&n=m.network_interfaces[i];o<<"{\"name\":\""<<json_escape(n.name)<<"\",\"rx_bytes\":"<<n.rx_bytes<<",\"tx_bytes\":"<<n.tx_bytes<<'}';}o<<"]}";return o.str();}
std::string read_file(const std::string&p){std::ifstream f(p);if(!f)return"<!doctype html><html><body><h1>EdgeShield AI</h1><p>Dashboard asset missing. See README.</p></body></html>";std::ostringstream s;s<<f.rdbuf();return s.str();}
std::string response(int code,const std::string&type,const std::string&body){std::string status=code==200?"OK":(code==404?"Not Found":"Bad Request");return"HTTP/1.1 "+std::to_string(code)+" "+status+"\r\nContent-Type: "+type+"\r\nContent-Length: "+std::to_string(body.size())+"\r\nConnection: close\r\nAccess-Control-Allow-Origin: *\r\n\r\n"+body;}
}
HttpServer::HttpServer(int p,std::string h):port_(p),host_(std::move(h)){}
int HttpServer::run(){int fd=::socket(AF_INET,SOCK_STREAM,0);if(fd<0){perror("socket");return 1;}int yes=1;setsockopt(fd,SOL_SOCKET,SO_REUSEADDR,&yes,sizeof(yes));sockaddr_in addr{};addr.sin_family=AF_INET;if(inet_pton(AF_INET,host_.c_str(),&addr.sin_addr)!=1){std::cerr<<"Invalid bind address: "<<host_<<std::endl;close(fd);return 1;}addr.sin_port=htons(static_cast<uint16_t>(port_));if(bind(fd,reinterpret_cast<sockaddr*>(&addr),sizeof(addr))<0||listen(fd,32)<0){perror("bind/listen");close(fd);return 1;}std::cout<<"EdgeShield C++ API listening on "<<host_<<":"<<port_<<std::endl;SciEngine sci;while(true){int c=accept(fd,nullptr,nullptr);if(c<0)continue;std::string req;char buf[4096];ssize_t n;while((n=recv(c,buf,sizeof(buf),0))>0){req.append(buf,static_cast<std::size_t>(n));auto h=req.find("\r\n\r\n");if(h!=std::string::npos){std::size_t len=0;auto cp=req.find("Content-Length:");if(cp!=std::string::npos){cp+=15;while(cp<req.size()&&req[cp]==' ')++cp;try{len=std::stoul(req.substr(cp));}catch(...){}}if(req.size()>=h+4+len)break;}}
 auto split=req.find("\r\n");std::istringstream first(req.substr(0,split));std::string method,path,ver;first>>method>>path>>ver;auto hp=req.find("\r\n\r\n");std::string body=hp==std::string::npos?"":req.substr(hp+4);std::string out;
 if(method=="GET"&&path=="/")out=response(200,"text/html; charset=utf-8",read_file("native/web/index.html"));
 else if(method=="GET"&&path=="/api/health")out=response(200,"application/json","{\"status\":\"ok\",\"service\":\"edgeshield-native\",\"version\":\"1.3.0\"}");
 else if(method=="GET"&&path=="/api/system/metrics")out=response(200,"application/json",metrics_json(SystemMonitor{}.sample()));
 else if(method=="GET"&&path=="/api/sci/incidents"){auto list=sci.list();std::ostringstream o;o<<"{\"incidents\":[";for(std::size_t i=0;i<list.size();++i){if(i)o<<',';auto&x=list[i];o<<"{\"incident_id\":\""<<json_escape(x.incident_id)<<"\",\"fault_domain\":\""<<json_escape(x.fault_domain)<<"\",\"diagnosis\":\""<<json_escape(x.diagnosis)<<"\",\"correction\":\""<<json_escape(x.correction)<<"\",\"verification_status\":\""<<x.verification_status<<"\",\"chain_checksum\":\""<<x.chain_checksum<<"\"}";}o<<"]}";out=response(200,"application/json",o.str());}
 else if(method=="POST"&&(path=="/api/analyze/url"||path=="/api/analyze/sms"||path=="/api/analyze/network")){DetectionResult r;if(path=="/api/analyze/url")r=UrlDetector{}.analyze(getstr(body,"url",getstr(body,"text")));else if(path=="/api/analyze/sms")r=SmsDetector{}.analyze(getstr(body,"message",getstr(body,"text")));else{NetworkFlow f;f.src_ip=getstr(body,"src_ip");f.dst_ip=getstr(body,"dst_ip");f.protocol=getstr(body,"protocol","tcp");f.src_port=static_cast<uint16_t>(getnum(body,"src_port"));f.dst_port=static_cast<uint16_t>(getnum(body,"dst_port"));f.packets=static_cast<uint64_t>(getnum(body,"packets"));f.bytes=static_cast<uint64_t>(getnum(body,"bytes"));f.syn_packets=static_cast<uint64_t>(getnum(body,"syn_packets"));f.rst_packets=static_cast<uint64_t>(getnum(body,"rst_packets"));f.failed_connections=static_cast<uint64_t>(getnum(body,"failed_connections"));f.duration_seconds=getnum(body,"duration_seconds");r=NetworkDetector{}.analyze(f);}r.event.event_id="evt-"+std::to_string(std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count());if(r.flagged){auto incident=sci.record(r.event,source_name(r.event.source),"Detection rule matched: "+r.event.category,"Review evidence and apply operator-approved containment; no automatic blocking is performed");(void)incident;}out=response(200,"application/json",event_json(r));}
 else if(method=="POST"&&path=="/api/sci/verify"){auto id=getstr(body,"incident_id");bool passed=body.find("\"passed\":true")!=std::string::npos;bool ok=sci.verify(id,passed);out=response(ok?200:400,"application/json",ok?"{\"status\":\"caller_check_passed\"}":"{\"status\":\"verification_not_passed_or_not_found\"}");}
 else { out=response(404,"application/json","{\"error\":\"not_found\"}"); }
 send(c,out.data(),out.size(),0);close(c);}
 close(fd);return 0;}
}
